const EXPECTED_SOURCE_PATHS = Object.freeze([
  "packages/core/src/decimal/contract.ts",
  "packages/core/src/decimal/probe-gates.ts",
  "packages/core/src/ir/semantics/deferred-expression-preflight.ts",
  "packages/core/src/ir/semantics/semantic-atomic-ownership.ts",
  "packages/core/src/runtime-envelope/value.ts"
]);
const EXPECTED_COMPILED_PATHS = Object.freeze([
  "decimal/contract.js",
  "decimal/probe-gates.js",
  "ir/semantics/deferred-expression-preflight.js",
  "ir/semantics/semantic-atomic-ownership.js",
  "runtime-envelope/value.js"
]);

function exactRows(rows, expectedPaths) {
  return (
    Array.isArray(rows) &&
    rows.length === expectedPaths.length &&
    rows.every((row, index) =>
      row?.claim === CLAIM &&
      row.path === expectedPaths[index] &&
      /^[0-9a-f]{64}$/u.test(row.currentDigest) &&
      /^[0-9a-f]{64}$/u.test(row.expectedDigest) &&
      Array.isArray(row.replacements) &&
      row.replacements.length > 0
    )
  );
}

export function decimalAdmissionIsolationCompiledReconstruction(path) {
  return POST_DECIMAL_ADMISSION_ISOLATION_COMPILED_RECONSTRUCTIONS.find((row) => row.path === path);
}

export function validateDecimalAdmissionIsolationHistoricalTransition({
  transition = DECIMAL_ADMISSION_ISOLATION_HISTORICAL_TRANSITION,
  sourceReconstructions = POST_DECIMAL_ADMISSION_ISOLATION_SOURCE_RECONSTRUCTIONS,
  compiledReconstructions = POST_DECIMAL_ADMISSION_ISOLATION_COMPILED_RECONSTRUCTIONS,
} = {}) {
  if (
    transition?.claim !== CLAIM ||
    transition.predecessorCommit !== PREDECESSOR_COMMIT ||
    transition.successorCommit !== SUCCESSOR_COMMIT ||
    JSON.stringify(transition.sourceManifest) !== '{"count":5,"digest":"fdf3bdf00ff36f7f50ecff15fee3daec639ee0d98dcd56543b8b49f672426419"}' ||
    JSON.stringify(transition.compiledManifest) !== '{"count":5,"digest":"f6e38d7500041a3b425b5b685c5a9cf019b325c1f963c2bde21f00882a2e63b6"}' ||
    JSON.stringify(transition.sourceEndpoints) !== '{"predecessor":"bbc8fcc0f6ca5cfb9af629ef3039d11b7f6fcd6191f35aead368326b1035783a","successor":"4415cf227ad8c30f63dd1da9538818d6761d1db1d1cd6ea4a4a7add642302eb8"}' ||
    JSON.stringify(transition.compiledEndpoints) !== '{"predecessor":"4f2e9d83b2ffb4f4a6d1d3723e3a6d027dd77b8255217a7decc1171c5aa0c421","successor":"399b5a406578ff3d1df1cf59ae2640f9769d4f95f4b319e46a2403dd3629e8d7"}' ||
    JSON.stringify(transition.compiledInventory?.predecessor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    JSON.stringify(transition.compiledInventory?.successor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    !exactRows(sourceReconstructions, EXPECTED_SOURCE_PATHS) ||
    !exactRows(compiledReconstructions, EXPECTED_COMPILED_PATHS)
  ) {
    throw new TypeError('decimal-admission isolation historical transition immutable identity changed');
  }
  return true;
}
